import * as path from "node:path";
import type { Command, CommanderError } from "commander";
import { z } from "zod";
import { callDaemon, ensureDaemon } from "../../daemon/ensure-daemon.js";
import { socketPath } from "../../daemon/paths.js";
import {
  DeleteFileArgsSchema,
  ExtractFunctionArgsSchema,
  FindImportersArgsSchema,
  FindReferencesArgsSchema,
  GetDefinitionArgsSchema,
  GetTypeErrorsArgsSchema,
  MoveArgsSchema,
  MoveDirectoryArgsSchema,
  MoveSymbolArgsSchema,
  RenameArgsSchema,
  ReplaceTextBaseSchema,
  SearchTextArgsSchema,
} from "../schema.js";
import { classifyDaemonError } from "./classify-error.js";

/**
 * Maps each kebab-case CLI subcommand name to the camelCase daemon method name
 * and lists which JSON keys hold file paths (for relative→absolute resolution).
 */
const SUBCOMMANDS: Record<
  string,
  { method: string; pathParams: string[]; schema: z.ZodType | null }
> = {
  rename: { method: "rename", pathParams: ["file"], schema: RenameArgsSchema },
  "move-file": { method: "moveFile", pathParams: ["oldPath", "newPath"], schema: MoveArgsSchema },
  "move-directory": {
    method: "moveDirectory",
    pathParams: ["oldPath", "newPath"],
    schema: MoveDirectoryArgsSchema,
  },
  "move-symbol": {
    method: "moveSymbol",
    pathParams: ["sourceFile", "destFile"],
    schema: MoveSymbolArgsSchema,
  },
  "extract-function": {
    method: "extractFunction",
    pathParams: ["file"],
    schema: ExtractFunctionArgsSchema,
  },
  "find-importers": {
    method: "findImporters",
    pathParams: ["file"],
    schema: FindImportersArgsSchema,
  },
  "find-references": {
    method: "findReferences",
    pathParams: ["file"],
    schema: FindReferencesArgsSchema,
  },
  "get-definition": {
    method: "getDefinition",
    pathParams: ["file"],
    schema: GetDefinitionArgsSchema,
  },
  "get-type-errors": {
    method: "getTypeErrors",
    pathParams: [],
    schema: GetTypeErrorsArgsSchema,
  },
  "search-text": { method: "searchText", pathParams: [], schema: SearchTextArgsSchema },
  "delete-file": { method: "deleteFile", pathParams: ["file"], schema: DeleteFileArgsSchema },
  "replace-text": { method: "replaceText", pathParams: [], schema: ReplaceTextBaseSchema },
};

export function writeJsonError(error: string, message: string): void {
  process.stdout.write(`${JSON.stringify({ status: "error", error, message })}\n`);
}

/**
 * Render a parameter breakdown block from a Zod object schema. Derives each
 * field's name, description, and whether it's optional from the schema, so the
 * help text can never drift from validation. Type is left to the description
 * (e.g. "Line number (1-based)") rather than coupling the help to Zod's
 * type-name rendering.
 */
function renderParamsHelp(schema: z.ZodType): string {
  const json = z.toJSONSchema(schema);
  const required = new Set(json.required ?? []);
  const rows: { name: string; desc: string }[] = [];
  for (const [name, prop] of Object.entries(json.properties ?? {})) {
    // JSON Schema permits a boolean in place of a property schema; ours never are.
    if (typeof prop === "boolean") continue;
    const optional = required.has(name) ? "" : "(optional) ";
    rows.push({ name, desc: `${optional}${prop.description ?? ""}` });
  }
  if (rows.length === 0) return "";

  const nameWidth = Math.max(...rows.map((r) => r.name.length));
  const lines = ["\nJSON parameters:"];
  for (const r of rows) {
    lines.push(`  ${r.name.padEnd(nameWidth)}  ${r.desc}`);
  }
  return lines.join("\n");
}

/**
 * Register all operation subcommands on the given Commander program.
 * Each subcommand accepts a single positional JSON argument or reads from stdin
 * when stdin is not a TTY.
 */
export function registerOperationSubcommands(
  program: Command,
  exitOverride: (err: CommanderError) => never,
): void {
  for (const [subcommand, { method, pathParams, schema }] of Object.entries(SUBCOMMANDS)) {
    const cmd = program
      .command(`${subcommand} [json]`)
      .description(`Invoke the ${method} operation`)
      .option("--workspace <path>", "Root directory of the project", process.cwd())
      .exitOverride(exitOverride);

    if (schema !== null) {
      cmd.addHelpText("after", () => renderParamsHelp(schema));
    }

    cmd.action(async (jsonArg: string | undefined, opts: { workspace: string }) => {
      const workspace = path.resolve(opts.workspace);

      const raw = await resolveInput(jsonArg, subcommand);
      if (raw === null) return; // resolveInput already printed help and exited

      let params: Record<string, unknown>;
      try {
        params = JSON.parse(raw) as Record<string, unknown>;
      } catch {
        writeJsonError("VALIDATION_ERROR", `Invalid JSON: ${raw}`);
        process.exit(1);
      }

      resolveRelativePaths(params, pathParams, workspace);

      try {
        await ensureDaemon(workspace);
        const response = await callDaemon(socketPath(workspace), { method, params });
        process.stdout.write(`${JSON.stringify(response)}\n`);

        if ((response as Record<string, unknown>).status === "error") {
          process.exit(1);
        }
      } catch (err: unknown) {
        const errorCode = classifyDaemonError(err);
        const message = err instanceof Error ? err.message : String(err);
        writeJsonError(errorCode, message);
        process.exit(1);
      }
    });
  }
}

/**
 * Resolve path parameters in-place: any path param that is a relative string
 * is joined to workspace to produce an absolute path.
 */
export function resolveRelativePaths(
  params: Record<string, unknown>,
  pathParams: string[],
  workspace: string,
): void {
  for (const key of pathParams) {
    const val = params[key];
    if (typeof val === "string" && !path.isAbsolute(val)) {
      params[key] = path.resolve(workspace, val);
    }
  }
}

async function resolveInput(
  jsonArg: string | undefined,
  subcommand: string,
): Promise<string | null> {
  if (jsonArg !== undefined) return jsonArg;
  if (!process.stdin.isTTY) return readStdin();
  writeJsonError(
    "VALIDATION_ERROR",
    `No JSON argument provided. Usage: weaver ${subcommand} '<json>'`,
  );
  process.exit(1);
}

function readStdin(): Promise<string> {
  return new Promise((resolve) => {
    let buf = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk: string) => {
      buf += chunk;
    });
    process.stdin.on("end", () => resolve(buf.trim()));
  });
}

src/daemon/dispatcher.ts.source:
import {
  DeleteFileArgsSchema,
  ExtractFunctionArgsSchema,
  FindImportersArgsSchema,
  FindReferencesArgsSchema,
  GetDefinitionArgsSchema,
  GetTypeErrorsArgsSchema,
  MoveArgsSchema,
  MoveDirectoryArgsSchema,
  MoveSymbolArgsSchema,
  RenameArgsSchema,
  ReplaceTextArgsSchema,
  SearchTextArgsSchema,
} from "../adapters/schema.js";
import { validateFilePath } from "../domain/security.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { extractFunction } from "../operations/extractFunction.js";
import { findImporters } from "../operations/findImporters.js";
import { findReferences } from "../operations/findReferences.js";
import { getDefinition } from "../operations/getDefinition.js";
import { getTypeErrors } from "../operations/getTypeErrors.js";
import { moveDirectory } from "../operations/moveDirectory.js";
import { moveFile } from "../operations/moveFile.js";
import { rename } from "../operations/rename.js";
import { replaceText } from "../operations/replaceText.js";
import { searchText } from "../operations/searchText.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import type { EngineRegistry } from "../ts-engine/types.js";
import { makeRegistry } from "./language-plugin-registry.js";
import { getTypeErrorsForFiles } from "./post-write-diagnostics.js";

export { createVueLanguagePlugin } from "../plugins/vue/plugin.js";
export type { LanguagePlugin } from "../ts-engine/types.js";
export {
  clearLanguagePlugins,
  invalidateAll,
  invalidateFile,
  makeRegistry,
  registerLanguagePlugin,
} from "./language-plugin-registry.js";

// ─── Operation descriptor table ───────────────────────────────────────────

interface OperationDescriptor {
  /** Param keys that hold file paths requiring workspace validation. */
  pathParams: string[];
  /** Zod schema used to validate incoming params at the socket boundary. */
  schema: {
    safeParse(
      data: unknown,
    ):
      | { success: true; data: Record<string, unknown> }
      | { success: false; error: { issues: Array<{ message: string }> } };
  };
  /** Call the appropriate compiler method and return the raw result. */
  invoke(
    registry: EngineRegistry,
    params: Record<string, unknown>,
    workspace: string,
  ): Promise<unknown>;
}

const OPERATIONS: Record<string, OperationDescriptor> = {
  rename: {
    pathParams: ["file"],
    schema: RenameArgsSchema,
    async invoke(registry, params, workspace) {
      const { file, line, col, newName } = params as {
        file: string;
        line: number;
        col: number;
        newName: string;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return rename(engine, file, line, col, newName, scope);
    },
  },

  moveFile: {
    pathParams: ["oldPath", "newPath"],
    schema: MoveArgsSchema,
    async invoke(registry, params, workspace) {
      const { oldPath, newPath } = params as { oldPath: string; newPath: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return moveFile(engine, oldPath, newPath, scope);
    },
  },

  moveDirectory: {
    pathParams: ["oldPath", "newPath"],
    schema: MoveDirectoryArgsSchema,
    async invoke(registry, params, workspace) {
      const { oldPath, newPath } = params as { oldPath: string; newPath: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return moveDirectory(engine, oldPath, newPath, scope);
    },
  },

  moveSymbol: {
    pathParams: ["sourceFile", "destFile"],
    schema: MoveSymbolArgsSchema,
    async invoke(registry, params, workspace) {
      const { sourceFile, symbolName, destFile, force } = params as {
        sourceFile: string;
        symbolName: string;
        destFile: string;
        force?: boolean;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      const { moveSymbol } = await import("../operations/moveSymbol.js");
      return moveSymbol(engine, sourceFile, symbolName, destFile, scope, { force });
    },
  },

  extractFunction: {
    pathParams: ["file"],
    schema: ExtractFunctionArgsSchema,
    async invoke(registry, params, workspace) {
      const { file, startLine, startCol, endLine, endCol, functionName } = params as {
        file: string;
        startLine: number;
        startCol: number;
        endLine: number;
        endCol: number;
        functionName: string;
      };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return extractFunction(
        engine,
        file,
        startLine,
        startCol,
        endLine,
        endCol,
        functionName,
        scope,
      );
    },
  },

  findImporters: {
    pathParams: ["file"],
    schema: FindImportersArgsSchema,
    async invoke(registry, params) {
      const { file } = params as { file: string };
      const engine = await registry.projectEngine();
      return findImporters(engine, file);
    },
  },

  findReferences: {
    pathParams: ["file"],
    schema: FindReferencesArgsSchema,
    async invoke(registry, params) {
      const { file, line, col } = params as { file: string; line: number; col: number };
      const engine = await registry.projectEngine();
      return findReferences(engine, file, line, col);
    },
  },

  getDefinition: {
    pathParams: ["file"],
    schema: GetDefinitionArgsSchema,
    async invoke(registry, params) {
      const { file, line, col } = params as { file: string; line: number; col: number };
      const engine = await registry.projectEngine();
      return getDefinition(engine, file, line, col);
    },
  },

  getTypeErrors: {
    pathParams: [],
    schema: GetTypeErrorsArgsSchema,
    async invoke(registry, params, workspace) {
      const { file } = params as { file?: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return getTypeErrors(engine, file, scope);
    },
  },

  searchText: {
    pathParams: [],
    schema: SearchTextArgsSchema,
    async invoke(_registry, params, workspace) {
      const { pattern, glob, context, maxResults } = params as {
        pattern: string;
        glob?: string;
        context?: number;
        maxResults?: number;
      };
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return searchText(pattern, scope, { glob, context, maxResults });
    },
  },

  deleteFile: {
    pathParams: ["file"],
    schema: DeleteFileArgsSchema,
    async invoke(registry, params, workspace) {
      const { file } = params as { file: string };
      const engine = await registry.projectEngine();
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      const { deleteFile } = await import("../operations/deleteFile.js");
      return deleteFile(engine, file, scope);
    },
  },

  replaceText: {
    pathParams: [],
    schema: ReplaceTextArgsSchema,
    async invoke(_registry, params, workspace) {
      const { pattern, replacement, glob, edits } = params as {
        pattern?: string;
        replacement?: string;
        glob?: string;
        edits?: Array<{
          file: string;
          line: number;
          col: number;
          oldText: string;
          newText: string;
        }>;
      };
      const scope = new WorkspaceScope(workspace, new NodeFileSystem());
      return replaceText(scope, { pattern, replacement, glob, edits });
    },
  },
};

/** Canonical list of dispatchable operation names — the single source of truth. */
export const OPERATION_NAMES: string[] = Object.keys(OPERATIONS);

// ─── Dispatcher ────────────────────────────────────────────────────────────

export async function dispatchRequest(
  req: { method: string; params: Record<string, unknown> },
  workspace: string,
): Promise<object> {
  const descriptor = OPERATIONS[req.method];
  if (!descriptor) {
    return {
      status: "error" as const,
      error: "UNKNOWN_METHOD",
      message: `Unknown method: ${req.method}`,
    };
  }

  const parsed = descriptor.schema.safeParse(req.params);
  if (!parsed.success) {
    const message = parsed.error.issues.map((i) => i.message).join("; ");
    return { status: "error" as const, error: "VALIDATION_ERROR", message };
  }

  for (const paramKey of descriptor.pathParams) {
    const value = req.params[paramKey] as string;
    const pathResult = validateFilePath(value);
    if (!pathResult.ok) {
      return {
        status: "error" as const,
        error: "INVALID_PATH",
        message:
          pathResult.reason === "CONTROL_CHARS"
            ? `path contains control characters: ${paramKey}`
            : `path contains URI fragment or query character: ${paramKey}`,
      };
    }
    if (!new WorkspaceScope(workspace, new NodeFileSystem()).contains(value)) {
      return {
        status: "error" as const,
        error: "WORKSPACE_VIOLATION",
        message: `${paramKey} is outside the workspace: ${value}`,
      };
    }
  }

  const registry =
    descriptor.pathParams.length > 0
      ? makeRegistry(req.params[descriptor.pathParams[0]] as string, workspace)
      : makeRegistry(workspace, workspace);

  const result = (await descriptor.invoke(registry, parsed.data, workspace)) as Record<
    string,
    unknown
  >;

  if (
    parsed.data.checkTypeErrors !== false &&
    Array.isArray(result.filesModified) &&
    (result.filesModified as string[]).length > 0
  ) {
    const tsEngine = await registry.tsEngine();
    const diagnostics = getTypeErrorsForFiles(
      tsEngine,
      result.filesModified as string[],
      new NodeFileSystem(),
    );
    result.typeErrors = diagnostics.typeErrors;
    result.typeErrorCount = diagnostics.typeErrorCount;
    result.typeErrorsTruncated = diagnostics.typeErrorsTruncated;
  }

  const status =
    typeof result.typeErrorCount === "number" && result.typeErrorCount > 0
      ? ("warn" as const)
      : ("success" as const);
  return { status, ...result };
}

src/adapters/cli/classify-error.ts.source:
export function classifyDaemonError(err: unknown): "DAEMON_STARTING" | "INTERNAL_ERROR" {
  if (!(err instanceof Error)) return "INTERNAL_ERROR";
  const code = (err as NodeJS.ErrnoException).code;
  if (code === "ECONNREFUSED" || code === "ENOENT" || code === "ECONNRESET")
    return "DAEMON_STARTING";
  if (err.message.includes("timed out")) return "DAEMON_STARTING";
  return "INTERNAL_ERROR";
}

