import { describe, expect } from "vitest";
import { FIXTURES, fileExists, readFile, fixtureTest as test } from "../__testHelpers__/helpers.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { VolarEngine } from "../plugins/vue/engine.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { TsMorphEngine } from "../ts-engine/engine.js";
import { moveDirectory } from "./moveDirectory.js";

function makeScope(dir: string): WorkspaceScope {
  return new WorkspaceScope(dir, new NodeFileSystem());
}

describe("moveDirectory action - VolarEngine integration", () => {
  describe("external .ts files importing moved .vue components", () => {
    test("updates path-alias import specifier in external .ts file after moving directory", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      await moveDirectory(compiler, `${dir}/src/components`, `${dir}/src/ui`, makeScope(dir));

      const appTs = readFile(dir, "src/app.ts");
      expect(appTs).not.toContain("@/components/Button.vue");
    });

    test("updates import specifier in external .ts file after moving directory with .vue files", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      await moveDirectory(compiler, `${dir}/src/components`, `${dir}/src/ui`, makeScope(dir));

      // The moved .vue file must be at the new location
      expect(fileExists(dir, "src/ui/Button.vue")).toBe(true);
      expect(fileExists(dir, "src/components/Button.vue")).toBe(false);

      // The external .ts file must have its import specifier updated
      const appTs = readFile(dir, "src/app.ts");
      expect(appTs).toContain("./ui/Button.vue");
      expect(appTs).not.toContain("./components/Button.vue");
    });

    test("updates import specifier in external .ts file when moving into a nested destination", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      await moveDirectory(
        compiler,
        `${dir}/src/components`,
        `${dir}/src/ui/widgets`,
        makeScope(dir),
      );

      const appTs = readFile(dir, "src/app.ts");
      expect(appTs).toContain("./ui/widgets/Button.vue");
      expect(appTs).not.toContain("./components/Button.vue");
    });
  });

  describe("external .vue files importing from moved directory", () => {
    test("updates import specifier in external .vue file after moving a composables directory", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      await moveDirectory(compiler, `${dir}/src/composables`, `${dir}/src/hooks`, makeScope(dir));

      // The moved .ts file must be at the new location
      expect(fileExists(dir, "src/hooks/useCounter.ts")).toBe(true);
      expect(fileExists(dir, "src/composables/useCounter.ts")).toBe(false);

      // The external .vue file must have its import specifier updated
      const appVue = readFile(dir, "src/App.vue");
      expect(appVue).toContain("./hooks/useCounter");
      expect(appVue).not.toContain("./composables/useCounter");
    });

    test("updates import specifier in external .vue file after moving a components directory with .vue files", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      await moveDirectory(compiler, `${dir}/src/components`, `${dir}/src/ui`, makeScope(dir));

      // App.vue also imports Button.vue from components — it must be updated
      const appVue = readFile(dir, "src/App.vue");
      expect(appVue).toContain("./ui/Button.vue");
      expect(appVue).not.toContain("./components/Button.vue");
    });
  });

  describe("moved .vue files with external relative imports", () => {
    test("updates relative import in moved .vue file that points outside the moved directory", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      // Button.vue imports '../lib/helper'; after moving components/ → ui/components/
      // the import should become '../../lib/helper'
      await moveDirectory(
        compiler,
        `${dir}/src/components`,
        `${dir}/src/ui/components`,
        makeScope(dir),
      );

      const buttonVue = readFile(dir, "src/ui/components/Button.vue");
      expect(buttonVue).toContain("../../lib/helper");
      // The single-depth path must not appear as a standalone specifier
      // (note: "../../lib/helper" contains "../lib/helper" as a substring,
      // so we check the full depth is correct)
      expect(buttonVue).not.toContain('"../lib/helper"');
      expect(buttonVue).not.toContain("'../lib/helper'");
    });

    test("does not rewrite intra-directory imports between moved .vue files", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.moveDirVueExternal.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      // Moving composables/ — useCounter.ts has no intra-dir imports, so this just
      // verifies the composable content is intact after the move
      await moveDirectory(compiler, `${dir}/src/composables`, `${dir}/src/hooks`, makeScope(dir));

      const composable = readFile(dir, "src/hooks/useCounter.ts");
      expect(composable).toContain("useCounter");
      expect(composable).toContain("ref");
    });
  });
});

src/ts-engine/rename.test.ts.source:
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { describe, expect, it } from "vitest";
import {
  copyFixture,
  FIXTURES,
  readFile,
  fixtureTest as test,
} from "../__testHelpers__/helpers.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { TsMorphEngine } from "./engine.js";
import { tsRename } from "./rename.js";

function makeScope(dir: string): WorkspaceScope {
  return new WorkspaceScope(dir, new NodeFileSystem());
}

// simple-ts fixture:
//   src/utils.ts  line 1, col 17 → "greetUser"
//   src/main.ts   imports and calls greetUser

describe("tsRename", () => {
  describe("successful renames", () => {
    test("renames a symbol at its declaration site and returns the old name", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      const result = await tsRename(
        engine,
        `${dir}/src/utils.ts`,
        1,
        17,
        "greetPerson",
        makeScope(dir),
      );

      expect(result.symbolName).toBe("greetUser");
      expect(result.newName).toBe("greetPerson");
      expect(result.filesModified).toHaveLength(2);
      expect(result.filesSkipped).toHaveLength(0);
      expect(result.locationCount).toBeGreaterThanOrEqual(2);

      expect(readFile(dir, "src/utils.ts")).toContain("greetPerson");
      expect(readFile(dir, "src/main.ts")).toContain("greetPerson");
      expect(readFile(dir, "src/utils.ts")).not.toContain("greetUser");
    });

    test("renames a symbol from a call site", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      const result = await tsRename(
        engine,
        `${dir}/src/main.ts`,
        3,
        13,
        "sayHello",
        makeScope(dir),
      );

      expect(result.symbolName).toBe("greetUser");
      expect(result.newName).toBe("sayHello");
      expect(result.filesModified).toHaveLength(2);
      expect(result.locationCount).toBeGreaterThanOrEqual(2);

      expect(readFile(dir, "src/utils.ts")).toContain("sayHello");
      expect(readFile(dir, "src/main.ts")).toContain("sayHello");
    });

    it("renames across three files (multi-importer)", async () => {
      const dir = copyFixture(FIXTURES.multiImporter.name);
      try {
        const engine = new TsMorphEngine();

        const result = await tsRename(engine, `${dir}/src/utils.ts`, 1, 17, "sum", makeScope(dir));

        expect(result.symbolName).toBe("add");
        expect(result.newName).toBe("sum");
        expect(result.filesModified).toHaveLength(3);
        expect(result.locationCount).toBeGreaterThanOrEqual(3);

        expect(readFile(dir, "src/utils.ts")).toContain("sum");
        expect(readFile(dir, "src/featureA.ts")).toContain("sum");
        expect(readFile(dir, "src/featureB.ts")).toContain("sum");
      } finally {
        fs.rmSync(dir, { recursive: true, force: true });
      }
    });
  });

  describe("error cases", () => {
    test("throws SYMBOL_NOT_FOUND for an out-of-range line", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      await expect(
        tsRename(engine, `${dir}/src/utils.ts`, 999, 1, "foo", makeScope(dir)),
      ).rejects.toMatchObject({ code: "SYMBOL_NOT_FOUND" });
    });

    test("throws RENAME_NOT_ALLOWED for a non-renameable symbol (e.g. a string literal)", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      // line 2 of utils.ts is `  return \`Hello, ${name}\`;`
      // col 12 points inside the string literal "Hello, " — cannot be renamed
      await expect(
        tsRename(engine, `${dir}/src/utils.ts`, 2, 12, "foo", makeScope(dir)),
      ).rejects.toMatchObject({ code: "RENAME_NOT_ALLOWED" });
    });
  });

  describe("workspace boundary enforcement", () => {
    test("skips files outside the workspace boundary and records them in filesSkipped", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      // Use a scope rooted at src/ so only files under src/ are in bounds.
      // main.ts is in-scope; if the rename engine hits files outside scope, they go to filesSkipped.
      const narrowScope = makeScope(`${dir}/src`);

      const result = await tsRename(
        engine,
        `${dir}/src/utils.ts`,
        1,
        17,
        "greetPerson",
        narrowScope,
      );

      // utils.ts and main.ts are both in src/ so both should be modified
      expect(result.filesModified).not.toHaveLength(0);
      expect(result.symbolName).toBe("greetUser");
      expect(result.newName).toBe("greetPerson");
    });

    test("does not call notifyFileWritten on the engine (TsMorphEngine is a no-op)", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      // This test documents the contract: tsRename never calls notifyFileWritten.
      // We verify indirectly: the rename succeeds and files on disk reflect the rename,
      // meaning tsRename manages writes through scope.writeFile only.
      const engine = new TsMorphEngine();
      const scope = makeScope(dir);

      const result = await tsRename(engine, `${dir}/src/utils.ts`, 1, 17, "greetPerson", scope);

      expect(result.filesModified).toContain(`${dir}/src/utils.ts`);
      expect(readFile(dir, "src/utils.ts")).toContain("greetPerson");
    });
  });

  describe("workspace expansion — files outside tsconfig.include", () => {
    test("rename updates a test file that is outside tsconfig.include", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine(dir);
      const utilsPath = path.join(dir, "src/utils.ts");

      await tsRename(engine, utilsPath, 1, 17, "welcomeUser", makeScope(dir));

      const testFileContent = readFile(dir, "tests/utils.test.ts");
      expect(testFileContent).toContain("welcomeUser");
      expect(testFileContent).not.toContain("greetUser");
    });

    test("findReferences returns a location in a test file outside tsconfig.include", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine(dir);
      const utilsPath = path.join(dir, "src/utils.ts");

      const offset = engine.resolveOffset(utilsPath, 1, 17);
      const refs = await engine.getReferencesAtPosition(utilsPath, offset);

      expect(refs).not.toBeNull();
      const testFile = path.join(dir, "tests/utils.test.ts");
      const refInTestFile = refs?.find((r) => r.fileName === testFile);
      expect(refInTestFile).toBeDefined();
    });
  });

  describe("return value shape", () => {
    test("returns all required fields with correct types", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      const result = await tsRename(
        engine,
        `${dir}/src/utils.ts`,
        1,
        17,
        "renamed",
        makeScope(dir),
      );

      expect(Array.isArray(result.filesModified)).toBe(true);
      expect(Array.isArray(result.filesSkipped)).toBe(true);
      expect(typeof result.symbolName).toBe("string");
      expect(typeof result.newName).toBe("string");
      expect(typeof result.locationCount).toBe("number");
      expect(result.locationCount).toBeGreaterThan(0);
      expect(result.newName).toBe("renamed");
    });

    test("nameMatches is a flat array", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      const result = await tsRename(
        engine,
        `${dir}/src/utils.ts`,
        1,
        17,
        "greetPerson",
        makeScope(dir),
      );

      expect(Array.isArray(result.nameMatches)).toBe(true);
    });

    it("nameMatches finds derived identifier names in modified files", async () => {
      // This test uses fs.mkdtempSync for a custom workspace structure
      const dir = fs.mkdtempSync(path.join(os.tmpdir(), "rename-matches-"));
      try {
        fs.mkdirSync(path.join(dir, "src"));
        fs.writeFileSync(
          path.join(dir, "src/provider.ts"),
          "export class TsProvider {}\nexport const tsProviderDefault = new TsProvider();\n",
        );

        const engine = new TsMorphEngine();
        // col 14: "export class |TsProvider {}"
        const result = await tsRename(
          engine,
          path.join(dir, "src/provider.ts"),
          1,
          14,
          "TsMorphCompiler",
          makeScope(dir),
        );

        // tsProviderDefault is a derived name the compiler did not rewrite
        expect(result.nameMatches?.length).toBeGreaterThan(0);
        expect(result.nameMatches?.some((s) => s.name === "tsProviderDefault")).toBe(true);
      } finally {
        fs.rmSync(dir, { recursive: true, force: true });
      }
    });

    test("locationCount matches the total number of rename locations", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const engine = new TsMorphEngine();

      const result = await tsRename(
        engine,
        `${dir}/src/utils.ts`,
        1,
        17,
        "greetPerson",
        makeScope(dir),
      );

      // simple-ts has greetUser in: export declaration, import, call site = 3 locations
      expect(result.locationCount).toBeGreaterThanOrEqual(2);
      // locationCount must match the actual total (not just modified file count)
      expect(result.locationCount).toBeGreaterThanOrEqual(result.filesModified.length);
    });
  });
});

