import * as fs from "node:fs";
import { describe, expect, vi } from "vitest";
import { FIXTURES, readFile, fixtureTest as test } from "../__testHelpers__/helpers.js";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { VolarEngine } from "../plugins/vue/engine.js";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { NodeFileSystem } from "../ports/node-filesystem.js";
import { makeMockCompiler } from "../ts-engine/__testHelpers__/mock-compiler.js";
import { TsMorphEngine } from "../ts-engine/engine.js";
import { rename } from "./rename.js";

function makeScope(workspace: string): WorkspaceScope {
  return new WorkspaceScope(workspace, new NodeFileSystem());
}

describe("rename action", () => {
  describe("with TsMorphEngine", () => {
    test("renames a function at its declaration site", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const compiler = new TsMorphEngine();

      const result = await rename(
        compiler,
        `${dir}/src/utils.ts`,
        1,
        17,
        "greetPerson",
        makeScope(dir),
      );

      expect(result.symbolName).toBe("greetUser");
      expect(result.newName).toBe("greetPerson");
      expect(result.filesModified).toHaveLength(2);

      expect(readFile(dir, "src/utils.ts")).toContain("greetPerson");
      expect(readFile(dir, "src/main.ts")).toContain("greetPerson");
    });

    test("renames a function from a call site", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const compiler = new TsMorphEngine();

      const result = await rename(
        compiler,
        `${dir}/src/main.ts`,
        3,
        13,
        "sayHello",
        makeScope(dir),
      );

      expect(result.symbolName).toBe("greetUser");
      expect(result.newName).toBe("sayHello");
      expect(result.filesModified).toHaveLength(2);

      expect(readFile(dir, "src/utils.ts")).toContain("sayHello");
      expect(readFile(dir, "src/main.ts")).toContain("sayHello");
    });

    test("throws FILE_NOT_FOUND for non-existent file", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const compiler = new TsMorphEngine();

      await expect(
        rename(compiler, `${dir}/src/doesNotExist.ts`, 1, 1, "foo", makeScope(dir)),
      ).rejects.toMatchObject({ code: "FILE_NOT_FOUND" });
    });

    test("throws SYMBOL_NOT_FOUND for out-of-range line", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.simpleTs.name);
      const compiler = new TsMorphEngine();

      await expect(
        rename(compiler, `${dir}/src/utils.ts`, 999, 1, "foo", makeScope(dir)),
      ).rejects.toMatchObject({ code: "SYMBOL_NOT_FOUND" });
    });
  });

  describe("with TsMorphEngine — multi-importer", () => {
    test("renames across three files (multi-importer)", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.multiImporter.name);
      const compiler = new TsMorphEngine();

      const result = await rename(compiler, `${dir}/src/utils.ts`, 1, 17, "sum", makeScope(dir));

      expect(result.symbolName).toBe("add");
      expect(result.newName).toBe("sum");
      expect(result.filesModified).toHaveLength(3);

      expect(readFile(dir, "src/utils.ts")).toContain("sum");
      expect(readFile(dir, "src/featureA.ts")).toContain("sum");
      expect(readFile(dir, "src/featureB.ts")).toContain("sum");
    });
  });

  describe("with VolarEngine", () => {
    test("renames a composable in a .ts file and updates .vue files", async ({
      seedNamedFixture,
    }) => {
      const dir = await seedNamedFixture(FIXTURES.vueProject.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      const filePath = `${dir}/src/composables/useCounter.ts`;
      const result = await rename(compiler, filePath, 1, 17, "useCount", makeScope(dir));

      expect(result.symbolName).toBe("useCounter");
      expect(result.newName).toBe("useCount");
      expect(result.filesModified.length).toBeGreaterThanOrEqual(2);

      const tsContent = readFile(dir, "src/composables/useCounter.ts");
      expect(tsContent).toContain("useCount");
      expect(tsContent).not.toContain("export function useCounter");

      const vueContent = readFile(dir, "src/App.vue");
      expect(vueContent).toContain("useCount");
    });

    test("does not rename symbols in dist/ .vue files", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.vueProject.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      // dist/ is conventionally gitignored so it can't live in the committed fixture
      fs.mkdirSync(`${dir}/dist`, { recursive: true });
      fs.writeFileSync(
        `${dir}/dist/App.vue`,
        `<script setup>\nimport { useCounter } from '../src/composables/useCounter';\n</script>\n`,
      );

      const filePath = `${dir}/src/composables/useCounter.ts`;
      const result = await rename(compiler, filePath, 1, 17, "useCount", makeScope(dir));

      expect(result.filesModified).not.toContain(`${dir}/dist/App.vue`);
      const distContent = fs.readFileSync(`${dir}/dist/App.vue`, "utf8");
      expect(distContent).toContain("useCounter");
    });

    test("throws FILE_NOT_FOUND for non-existent file", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.vueProject.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      await expect(
        rename(compiler, `${dir}/src/doesNotExist.ts`, 1, 1, "foo", makeScope(dir)),
      ).rejects.toMatchObject({ code: "FILE_NOT_FOUND" });
    });
  });

  describe("with VolarEngine — vue-ts-boundary", () => {
    test("renames across TypeScript/Vue boundary", async ({ seedNamedFixture }) => {
      const dir = await seedNamedFixture(FIXTURES.vueTsBoundary.name);
      const compiler = new VolarEngine(new TsMorphEngine());

      const result = await rename(
        compiler,
        `${dir}/src/utils.ts`,
        1,
        17,
        "welcomeUser",
        makeScope(dir),
      );

      expect(result.symbolName).toBe("greetUser");
      expect(result.newName).toBe("welcomeUser");
      expect(result.filesModified.length).toBeGreaterThanOrEqual(2);

      expect(readFile(dir, "src/utils.ts")).toContain("welcomeUser");
      expect(readFile(dir, "src/App.vue")).toContain("welcomeUser");
      expect(readFile(dir, "src/App.vue")).not.toContain("greetUser");
    });
  });

  describe("via mock engine", () => {
    const sourceFile = "/ws/src/auth.ts";

    function scopeWith(file: string): WorkspaceScope {
      const vfs = new InMemoryFileSystem();
      vfs.writeFile(file, "");
      return new WorkspaceScope("/ws", vfs);
    }

    test("delegates to engine.rename() and returns the result", async () => {
      const expected = {
        filesModified: [sourceFile],
        filesSkipped: [],
        symbolName: "greetUser",
        newName: "greetPerson",
        locationCount: 2,
      };
      const compiler = makeMockCompiler({
        rename: vi.fn().mockResolvedValue(expected),
      });

      const scope = scopeWith(sourceFile);
      const result = await rename(compiler, sourceFile, 1, 17, "greetPerson", scope);

      expect(result).toEqual(expected);
      expect(compiler.rename).toHaveBeenCalledWith(sourceFile, 1, 17, "greetPerson", scope);
    });

    test("propagates errors thrown by engine.rename()", async () => {
      const compiler = makeMockCompiler({
        rename: vi.fn().mockRejectedValue({ code: "SYMBOL_NOT_FOUND" }),
      });

      const scope = scopeWith(sourceFile);

      await expect(rename(compiler, sourceFile, 1, 17, "newName", scope)).rejects.toMatchObject({
        code: "SYMBOL_NOT_FOUND",
      });
    });
  });
});

src/ts-engine/non-exported-declaration.t.source:
import { Project } from "ts-morph";
import { describe, expect, it } from "vitest";
import { findNonExportedDeclaration } from "./non-exported-declaration.js";

function makeProject() {
  return new Project({ useInMemoryFileSystem: true });
}

describe("findNonExportedDeclaration", () => {
  describe("returns null when no matching declaration exists", () => {
    it("returns null for an empty file", () => {
      const project = makeProject();
      const sf = project.createSourceFile("/dst.ts", "");

      expect(findNonExportedDeclaration(sf, "Foo")).toBeNull();
    });

    it("returns null when only unrelated declarations exist", () => {
      const project = makeProject();
      const sf = project.createSourceFile("/dst.ts", "function Bar(): void {}\n");

      expect(findNonExportedDeclaration(sf, "Foo")).toBeNull();
    });
  });

  describe("returns null when declaration is exported", () => {
    it.each([
      ["function", "export function Foo(): void {}\n"],
      ["class", "export class Foo {}\n"],
      ["interface", "export interface Foo { x: number }\n"],
      ["type alias", "export type Foo = string;\n"],
      ["const variable", "export const Foo = 1;\n"],
    ])("returns null for exported %s", (_kind, content) => {
      const project = makeProject();
      const sf = project.createSourceFile("/dst.ts", content);

      expect(findNonExportedDeclaration(sf, "Foo")).toBeNull();
    });
  });

  describe("returns the declaration node for non-exported declarations", () => {
    it.each([
      ["function", "function Foo(): void {}\nexport function other(): void {}\n"],
      ["class", "class Foo {}\nexport function other(): void {}\n"],
      ["interface", "interface Foo { x: number }\nexport function other(): void {}\n"],
      ["type alias", "type Foo = string;\nexport function other(): void {}\n"],
      ["const variable", "const Foo = 1;\nexport function other(): void {}\n"],
    ])("finds non-exported %s", (_kind, content) => {
      const project = makeProject();
      const sf = project.createSourceFile("/dst.ts", content);

      const result = findNonExportedDeclaration(sf, "Foo");

      expect(result).not.toBeNull();
      expect(typeof result?.remove).toBe("function");
    });

    it("returned node can be removed without error", () => {
      const project = makeProject();
      const sf = project.createSourceFile(
        "/dst.ts",
        "function Foo(): void {}\nexport function other(): void {}\n",
      );

      const result = findNonExportedDeclaration(sf, "Foo");
      result?.remove();

      expect(sf.getText()).not.toContain("function Foo");
      expect(sf.getText()).toContain("other");
    });
  });
});

src/plugins/vue/engine.deleteFile.test.t.source:
import * as fs from "node:fs";
import * as path from "node:path";
import { expect } from "vitest";
import { FIXTURES, fixtureTest as test } from "../../__testHelpers__/helpers.js";
import { WorkspaceScope } from "../../domain/workspace-scope.js";
import { NodeFileSystem } from "../../ports/node-filesystem.js";
import { TsMorphEngine } from "../../ts-engine/engine.js";
import { VolarEngine } from "./engine.js";

function makeScope(root: string): WorkspaceScope {
  return new WorkspaceScope(root, new NodeFileSystem());
}

test("removes named and type-only import lines from Vue script blocks", async ({
  seedNamedFixture,
}) => {
  const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
  const vueFile = path.join(dir, "src", "Comp.vue");
  fs.writeFileSync(
    vueFile,
    [
      '<script setup lang="ts">',
      "import { targetFn } from './target';",
      "import type { TargetType } from './target';",
      "import * as All from './target';",
      "const x = targetFn();",
      "</script>",
      "<template><div>hello</div></template>",
    ].join("\n"),
    "utf8",
  );

  const scope = makeScope(dir);
  const p = new VolarEngine(new TsMorphEngine());
  await p.deleteFile(`${dir}/src/target.ts`, scope);

  expect(scope.modified).toContain(vueFile);
  const content = fs.readFileSync(vueFile, "utf8");
  expect(content).not.toMatch(/from ['"]\.\/target['"]/);
  expect(content).toContain("const x = targetFn();");
  expect(content).toContain("<template>");
});

test("removes bare side-effect import lines from Vue script blocks", async ({
  seedNamedFixture,
}) => {
  const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
  const vueFile = path.join(dir, "src", "SideEffect.vue");
  fs.writeFileSync(
    vueFile,
    ["<script setup>", "import './target';", "const x = 1;", "</script>"].join("\n"),
    "utf8",
  );

  const scope = makeScope(dir);
  const p = new VolarEngine(new TsMorphEngine());
  await p.deleteFile(`${dir}/src/target.ts`, scope);

  expect(scope.modified).toContain(vueFile);
  const content = fs.readFileSync(vueFile, "utf8");
  expect(content).not.toContain("import './target'");
  expect(content).toContain("const x = 1;");
});

test("does not modify Vue files that do not import the deleted file", async ({
  seedNamedFixture,
}) => {
  const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
  const originalContent = [
    "<script setup>",
    "import { other } from './other-module';",
    "const x = 1;",
    "</script>",
  ].join("\n");
  const vueFile = path.join(dir, "src", "Unrelated.vue");
  fs.writeFileSync(vueFile, originalContent, "utf8");

  const scope = makeScope(dir);
  const p = new VolarEngine(new TsMorphEngine());
  await p.deleteFile(`${dir}/src/target.ts`, scope);

  expect(fs.readFileSync(vueFile, "utf8")).toBe(originalContent);
  expect(scope.modified).not.toContain(vueFile);
});

test("counts Vue import removals in importRefsRemoved on top of TS refs", async ({
  seedNamedFixture,
}) => {
  const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
  const vueFile = path.join(dir, "src", "VueRefs.vue");
  fs.writeFileSync(
    vueFile,
    [
      "<script setup>",
      "import { targetFn } from './target';",
      "import type { TargetType } from './target';",
      "</script>",
    ].join("\n"),
    "utf8",
  );

  // TS files: importer.ts (2) + barrel.ts (2) + tests/out-of-project.ts (1) = 5
  // Vue file adds 2 more = 7 total
  // TsMorphEngine(dir) expands the project graph to include tests/out-of-project.ts
  const scope = makeScope(dir);
  const p = new VolarEngine(new TsMorphEngine(dir));
  const result = await p.deleteFile(`${dir}/src/target.ts`, scope);

  expect(result.importRefsRemoved).toBe(7);
});

test("also removes TS importers when deleting a TS file via VolarEngine", async ({
  seedNamedFixture,
}) => {
  const dir = await seedNamedFixture(FIXTURES.deleteFileTs.name);
  const scope = makeScope(dir);
  const p = new VolarEngine(new TsMorphEngine());
  await p.deleteFile(`${dir}/src/target.ts`, scope);

  expect(scope.modified).toContain(`${dir}/src/importer.ts`);
  expect(fs.readFileSync(path.join(dir, "src/importer.ts"), "utf8")).not.toMatch(
    /from ['"]\.\/target['"]/,
  );
});

