import { describe, expect, it } from "vitest";
import { WorkspaceScope } from "../domain/workspace-scope.js";
import { InMemoryFileSystem } from "../ports/in-memory-filesystem.js";
import { ImportRewriter } from "./import-rewriter.js";

const ROOT = "/project";

function makeScope(files: Record<string, string> = {}): WorkspaceScope {
  const vfs = new InMemoryFileSystem();
  for (const [path, content] of Object.entries(files)) {
    vfs.writeFile(path, content);
  }
  return new WorkspaceScope(ROOT, vfs);
}

function readFile(scope: WorkspaceScope, path: string): string {
  return scope.fs.readFile(path);
}

describe("ImportRewriter", () => {
  const rewriter = new ImportRewriter();

  describe("full-move: all named imports match", () => {
    it("repoints the module specifier to the new destination", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn } from "./utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      expect(result).toContain(`from "./helpers.js"`);
      expect(result).not.toContain(`from "./utils.js"`);
    });

    it("records the file as modified", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn } from "./utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(scope.modified).toContain("/project/src/consumer.ts");
    });

    it("handles bare specifier (no extension) pointing at source file", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn } from "./utils";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      expect(result).toContain(`from "./helpers.js"`);
      expect(result).not.toContain(`"./utils"`);
    });

    it("handles .ts extension specifier", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn } from "./utils.ts";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      expect(result).toContain(`from "./helpers.js"`);
      expect(result).not.toContain(`"./utils.ts"`);
    });
  });

  describe("partial-move: symbol is one of several imports", () => {
    it("removes symbol from old import and adds a new import from destination", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn, OtherFn } from "./utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      // Old import keeps OtherFn but NOT MyFn
      expect(result).toMatch(/import\s*\{[^}]*OtherFn[^}]*\}\s*from\s*["']\.\/utils\.js["']/);
      expect(result).not.toMatch(/import\s*\{[^}]*MyFn[^}]*\}\s*from\s*["']\.\/utils\.js["']/);
      // New import has MyFn from helpers
      expect(result).toMatch(/import\s*\{[^}]*MyFn[^}]*\}\s*from\s*["']\.\/helpers\.js["']/);
    });

    it("does not lose the remaining symbol after the split", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { A, B, C } from "./utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "B",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      expect(result).toContain("A");
      expect(result).toContain("C");
      expect(result).toContain(`from "./helpers.js"`);
    });
  });

  describe("merge with existing destination import", () => {
    it("merges a full-move into an existing import — single import declaration for dest", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn } from "./utils.js";\nimport { ExistingFn } from "./helpers.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      // Both symbols appear in a single import from helpers
      expect(result).toContain("MyFn");
      expect(result).toContain("ExistingFn");
      // The old utils import is removed entirely
      expect(result).not.toContain(`from "./utils.js"`);
      // Only one import declaration for helpers (merged, not duplicated)
      const helperImports = result.match(/from ["']\.\/helpers\.js["']/g);
      expect(helperImports).toHaveLength(1);
    });

    it("merges a partial-move into an existing import from the destination", () => {
      const scope = makeScope({
        "/project/src/consumer.ts": `import { MyFn, OtherFn } from "./utils.js";\nimport { ExistingFn } from "./helpers.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/consumer.ts");
      // MyFn merged into existing helpers import
      expect(result).toContain("MyFn");
      expect(result).toContain("ExistingFn");
      // OtherFn stays on the old utils import
      expect(result).toContain("OtherFn");
      expect(result).toContain(`from "./utils.js"`);
      // Only one import from helpers (merged, not a second declaration)
      const helperImports = result.match(/from ["']\.\/helpers\.js["']/g);
      expect(helperImports).toHaveLength(1);
    });
  });

  describe("export re-exports", () => {
    it("repoints a full re-export specifier to the new destination", () => {
      const scope = makeScope({
        "/project/src/barrel.ts": `export { MyFn } from "./utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/barrel.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/barrel.ts");
      expect(result).toContain(`from "./helpers.js"`);
      expect(result).not.toContain(`from "./utils.js"`);
    });

    it("splits a partial re-export into old and new export declarations", () => {
      const scope = makeScope({
        "/project/src/barrel.ts": `export { MyFn, OtherFn } from "./utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/barrel.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/barrel.ts");
      // Old export keeps OtherFn but NOT MyFn
      expect(result).toMatch(/export\s*\{[^}]*OtherFn[^}]*\}\s*from\s*["']\.\/utils\.js["']/);
      expect(result).not.toMatch(/export\s*\{[^}]*MyFn[^}]*\}\s*from\s*["']\.\/utils\.js["']/);
      // New export has MyFn from helpers
      expect(result).toMatch(/export\s*\{[^}]*MyFn[^}]*\}\s*from\s*["']\.\/helpers\.js["']/);
    });
  });

  describe("no-op cases", () => {
    it.each([
      ["symbol not imported at all", `import { SomethingElse } from "./utils.js";\n`],
      [
        "imports from old source but not the moved symbol",
        `import { OtherFn } from "./utils.js";\n`,
      ],
      ["bare export with no module specifier", `const MyFn = () => {};\nexport { MyFn };\n`],
      ["imports symbol from an unrelated module", `import { MyFn } from "./other.js";\n`],
    ])("does not modify file when %s", (_desc, original) => {
      const scope = makeScope({ "/project/src/consumer.ts": original });
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(readFile(scope, "/project/src/consumer.ts")).toBe(original);
      expect(scope.modified).not.toContain("/project/src/consumer.ts");
    });

    it("handles an empty files iterable without error", () => {
      const scope = makeScope();
      expect(() =>
        rewriter.rewrite([], "MyFn", "/project/src/utils.ts", "/project/src/helpers.ts", scope),
      ).not.toThrow();
      expect(scope.modified).toHaveLength(0);
    });
  });

  describe("out-of-workspace files", () => {
    it("records a file outside the workspace as skipped without modifying it", () => {
      const scope = makeScope({
        "/external/consumer.ts": `import { MyFn } from "../project/src/utils.js";\n`,
      });
      rewriter.rewrite(
        ["/external/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(scope.skipped).toContain("/external/consumer.ts");
      expect(scope.modified).not.toContain("/external/consumer.ts");
    });

    it("does not write to a file outside the workspace", () => {
      const original = `import { MyFn } from "../project/src/utils.js";\n`;
      const vfs = new InMemoryFileSystem();
      vfs.writeFile("/external/consumer.ts", original);
      const scope = new WorkspaceScope(ROOT, vfs);
      rewriter.rewrite(
        ["/external/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(vfs.readFile("/external/consumer.ts")).toBe(original);
    });
  });

  describe("rewriteScript standalone", () => {
    it("rewrites script content without reading/writing files", () => {
      const content = `import { MyFn } from "./utils.js";\n`;
      const scope = makeScope();
      const result = rewriter.rewriteScript(
        "/project/src/component.ts",
        content,
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(result).toContain(`from "./helpers.js"`);
      expect(result).not.toContain(`from "./utils.js"`);
    });

    it("returns null when no matching declarations found", () => {
      const content = `import { Other } from "./other.js";\n`;
      const scope = makeScope();
      const result = rewriter.rewriteScript(
        "/project/src/component.ts",
        content,
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(result).toBeNull();
    });
  });

  describe("specifier extension matching", () => {
    it("skips a .js specifier that resolves to a real .js file on disk", () => {
      const original = `import { MyFn } from "./utils.js";\n`;
      const vfs = new InMemoryFileSystem();
      vfs.writeFile("/project/src/consumer.ts", original);
      vfs.writeFile("/project/src/utils.js", "// real js file");
      const scope = new WorkspaceScope(ROOT, vfs);
      rewriter.rewrite(
        ["/project/src/consumer.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      expect(readFile(scope, "/project/src/consumer.ts")).toBe(original);
      expect(scope.modified).not.toContain("/project/src/consumer.ts");
    });
  });

  describe("cross-directory imports", () => {
    it("computes correct specifiers for files in different directories", () => {
      const scope = makeScope({
        "/project/src/features/feature.ts": `import { MyFn } from "../utils.js";\n`,
      });
      rewriter.rewrite(
        ["/project/src/features/feature.ts"],
        "MyFn",
        "/project/src/utils.ts",
        "/project/src/helpers.ts",
        scope,
      );
      const result = readFile(scope, "/project/src/features/feature.ts");
      expect(result).toContain(`from "../helpers.js"`);
      expect(result).not.toContain(`from "../utils.js"`);
    });
  });
});

src/daemon/ensure-daemon.test.ts.source:
/**
 * Unit tests for ensureDaemon — daemon lifecycle management.
 *
 * Uses vi.resetModules() per test to reset the module-level versionVerified
 * flag. External calls are mocked at the module boundary (daemon.ts, paths.ts,
 * child_process). The callDaemon ping uses a real in-process Unix socket
 * server so the socket protocol is exercised without network I/O.
 */
import { EventEmitter } from "node:events";
import * as fs from "node:fs";
import * as net from "node:net";
import * as path from "node:path";
import * as tmp from "tmp";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// ─── Mutable stubs referenced by vi.mock factories ──────────────────────────

const mockIsDaemonAlive = vi.fn<() => boolean>();
const mockRemoveDaemonFiles = vi.fn<() => void>();
const mockStopDaemon = vi.fn<() => Promise<void>>();
const mockSpawn = vi.fn();

// socketPath is controlled per-test so servers and the code under test agree.
let currentSockPath = "";

vi.mock("../../src/daemon/daemon.js", () => ({
  isDaemonAlive: (w: string) => mockIsDaemonAlive(w),
  removeDaemonFiles: (w: string) => mockRemoveDaemonFiles(w),
  stopDaemon: (w: string) => mockStopDaemon(w),
  PROTOCOL_VERSION: 1,
}));

vi.mock("../../src/daemon/paths.js", () => ({
  socketPath: (_w: string) => currentSockPath,
}));

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, spawn: (...args: unknown[]) => mockSpawn(...args) };
});

// ─── Helpers ─────────────────────────────────────────────────────────────────

const WORKSPACE = "/test/workspace";

/** Unix socket server that responds to any request with { status: "success", version }. */
function createPingServer(sockPath: string, version: number): Promise<net.Server> {
  return new Promise((resolve) => {
    const server = net.createServer((conn) => {
      let buf = "";
      conn.on("data", (chunk: Buffer) => {
        buf += chunk.toString();
        if (buf.includes("\n")) {
          conn.write(`${JSON.stringify({ status: "success", version })}\n`);
          conn.end();
        }
      });
    });
    server.listen(sockPath, () => resolve(server));
  });
}

function closeServer(server: net.Server): Promise<void> {
  return new Promise((resolve) => server.close(() => resolve()));
}

/**
 * Fake child process returned by the mocked spawn.
 * opts.ready=true (default): emits { status: "ready" } on stderr after a tick.
 * opts.exitCode: emits "exit" instead (simulates daemon crash before ready).
 */
class FakeStderr extends EventEmitter {
  destroy = vi.fn();
}

class FakeChild extends EventEmitter {
  stderr = new FakeStderr();
  unref = vi.fn();
}

function makeFakeChild(opts: { ready?: boolean; exitCode?: number } = { ready: true }) {
  const child = new FakeChild();

  if (opts.exitCode !== undefined) {
    setTimeout(() => child.emit("exit", opts.exitCode), 0);
  } else if (opts.ready !== false) {
    setTimeout(
      () => child.stderr.emit("data", Buffer.from(`${JSON.stringify({ status: "ready" })}\n`)),
      0,
    );
  }
  return child;
}

// ─── Per-test setup / teardown ───────────────────────────────────────────────

let ensureDaemon: (workspace: string) => Promise<void>;
const activeServers: net.Server[] = [];
let tmpDir: tmp.DirResult;

beforeEach(async () => {
  tmpDir = tmp.dirSync({ unsafeCleanup: true });
  currentSockPath = path.join(tmpDir.name, "test.sock");

  mockIsDaemonAlive.mockReset().mockReturnValue(false);
  mockRemoveDaemonFiles.mockReset();
  mockStopDaemon.mockReset().mockResolvedValue(undefined);
  mockSpawn.mockReset();

  // Fresh module instance resets the module-level versionVerified to false.
  vi.resetModules();
  const mod = await import("./ensure-daemon.js");
  ensureDaemon = mod.ensureDaemon;
});

afterEach(async () => {
  for (const server of activeServers.splice(0)) await closeServer(server);
  tmpDir.removeCallback();
  vi.restoreAllMocks();
});

// ─── Tests ───────────────────────────────────────────────────────────────────

describe("ensureDaemon", () => {
  describe("stale socket", () => {
    it("removes stale files and spawns when socket exists but process is dead", async () => {
      fs.writeFileSync(currentSockPath, ""); // socket file present on disk
      mockIsDaemonAlive.mockReturnValue(false);
      mockSpawn.mockReturnValue(makeFakeChild({ ready: true }));

      await ensureDaemon(WORKSPACE);

      expect(mockRemoveDaemonFiles).toHaveBeenCalledWith(WORKSPACE);
      expect(mockSpawn).toHaveBeenCalled();
    });

    it("spawns directly without cleanup when no socket file exists", async () => {
      mockIsDaemonAlive.mockReturnValue(false);
      mockSpawn.mockReturnValue(makeFakeChild({ ready: true }));

      await ensureDaemon(WORKSPACE);

      expect(mockRemoveDaemonFiles).not.toHaveBeenCalled();
      expect(mockSpawn).toHaveBeenCalled();
    });
  });

  describe("live daemon", () => {
    describe("already version-verified this session", () => {
      it("returns immediately without pinging", async () => {
        // First call: no server → connection error → catch sets versionVerified = true
        mockIsDaemonAlive.mockReturnValue(true);
        await ensureDaemon(WORKSPACE);

        // Tripwire: if a second ping were attempted against this wrong-version server,
        // stopDaemon would be called and reveal it.
        const tripwire = await createPingServer(currentSockPath, 99);
        activeServers.push(tripwire);

        await ensureDaemon(WORKSPACE);

        expect(mockStopDaemon).not.toHaveBeenCalled();
        expect(mockSpawn).not.toHaveBeenCalled();
      });
    });

    describe("version matches", () => {
      it("returns without stopping or spawning", async () => {
        const server = await createPingServer(currentSockPath, 1); // PROTOCOL_VERSION = 1
        activeServers.push(server);
        mockIsDaemonAlive.mockReturnValue(true);

        await ensureDaemon(WORKSPACE);

        expect(mockSpawn).not.toHaveBeenCalled();
        expect(mockStopDaemon).not.toHaveBeenCalled();
        expect(mockRemoveDaemonFiles).not.toHaveBeenCalled();
      });
    });

    describe("version mismatch", () => {
      it("stops the old daemon and spawns a fresh one", async () => {
        const server = await createPingServer(currentSockPath, 0); // version 0 ≠ 1
        activeServers.push(server);
        mockIsDaemonAlive.mockReturnValue(true);
        // mockImplementation so the fake child and its setTimeout(0) are created
        // at spawn() call time, not test-setup time — the async ping would cause
        // a pre-created child's timer to fire before stderr.on("data") is registered.
        mockSpawn.mockImplementation(() => makeFakeChild({ ready: true }));

        await ensureDaemon(WORKSPACE);

        expect(mockStopDaemon).toHaveBeenCalledWith(WORKSPACE);
        expect(mockSpawn).toHaveBeenCalled();
      });
    });

    describe("ping fails unexpectedly", () => {
      it("marks as verified and returns without spawning", async () => {
        // No server at sockPath → ECONNREFUSED / ENOENT → callDaemon rejects
        mockIsDaemonAlive.mockReturnValue(true);

        await ensureDaemon(WORKSPACE); // must resolve, not reject

        expect(mockSpawn).not.toHaveBeenCalled();
        expect(mockStopDaemon).not.toHaveBeenCalled();
      });
    });
  });

  describe("no daemon running", () => {
    it("spawns with daemon command, workspace arg, and detached stdio options", async () => {
      mockIsDaemonAlive.mockReturnValue(false);
      mockSpawn.mockReturnValue(makeFakeChild({ ready: true }));

      await ensureDaemon(WORKSPACE);

      expect(mockSpawn).toHaveBeenCalledOnce();
      const [, spawnArgs, spawnOpts] = mockSpawn.mock.calls[0] as [
        string,
        string[],
        Record<string, unknown>,
      ];
      expect(spawnArgs).toContain("daemon");
      expect(spawnArgs).toContain("--workspace");
      expect(spawnArgs).toContain(WORKSPACE);
      expect(spawnOpts).toMatchObject({
        stdio: ["ignore", "ignore", "pipe"],
        detached: true,
      });
    });

    it("rejects when the daemon exits before signalling ready", async () => {
      mockIsDaemonAlive.mockReturnValue(false);
      mockSpawn.mockReturnValue(makeFakeChild({ exitCode: 1 }));

      await expect(ensureDaemon(WORKSPACE)).rejects.toThrow(/exited unexpectedly/i);
    });

    it("rejects rather than resolving on a non-ready stderr line before crash", async () => {
      mockIsDaemonAlive.mockReturnValue(false);

      const child = new FakeChild();
      setTimeout(() => {
        child.stderr.emit("data", Buffer.from(`${JSON.stringify({ status: "starting" })}\n`));
        child.emit("exit", 1);
      }, 0);
      mockSpawn.mockImplementation(() => child);

      await expect(ensureDaemon(WORKSPACE)).rejects.toThrow(/exited unexpectedly/i);
    });

    it("detaches the child's stderr pipe and exit listener so the parent can exit", async () => {
      mockIsDaemonAlive.mockReturnValue(false);
      const child = makeFakeChild({ ready: true });
      mockSpawn.mockReturnValue(child);

      await ensureDaemon(WORKSPACE);

      expect(child.stderr.destroy).toHaveBeenCalled();
      expect(child.unref).toHaveBeenCalled();
      expect(child.listenerCount("exit")).toBe(0);
    });

    it("skips ping on the next call after a successful spawn", async () => {
      mockIsDaemonAlive.mockReturnValue(false);
      mockSpawn.mockImplementation(() => makeFakeChild({ ready: true }));
      await ensureDaemon(WORKSPACE);

      // Tripwire: if a ping were attempted, the wrong version would trigger stopDaemon.
      mockIsDaemonAlive.mockReturnValue(true);
      const tripwire = await createPingServer(currentSockPath, 99);
      activeServers.push(tripwire);

      await ensureDaemon(WORKSPACE);

      expect(mockStopDaemon).not.toHaveBeenCalled();
      expect(mockSpawn).toHaveBeenCalledOnce();
    });
  });
});

